Lemma shiftr_ff_112 : forall ff, ff mod 8 = 0 -> Z.shiftr (ff + 112) 3 = Z.shiftr ff 3 + 14.
Proof. intros ff F8. rewrite !Z.shiftr_div_pow2 by lia. change (2^3) with 8. Z.div_mod_to_equations. lia. Qed.

