(* [comment removed for export] *)
Definition rs_read1_post (sp : word) (spa : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (LF : list fframe)
    (lo shi E bs fb P tot k ff fp : Z) (FB : fbv) (iseof : bool) (hw : word) (tmp gap optc : list cell) (j56 j120 : list byte) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists m' (rax t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
       ms' = MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) (wz (if iseof then 1 else 0)) a1 a2 a3 a4 a5 a6 a7
                     (wz (ff + 96)) (wz tot) (wz E) (wz k) (wz (E + 16)) (wz (Z.shiftr ff 3 + 2147450880)) (wz (fb + 16)) (wz 2147450880)
                     (wz AGENID) (wz tot) t3 t4 t5 t6)
                F (Z_to_bv 64 RS_CMP) fc None m' (seg_rom bsegs)
    /\ munch [(lo, spa); (fb + 16, fb + 24); (ff + 96, ff + 96 + 24); (Z.shiftr ff 3 + 2147450880 + 12, Z.shiftr ff 3 + 2147450880 + 15)]%Z m m'
    /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo spa
    /\ rs_frame m' sp spa ff E bs P fb (C8 (wz (Z.shiftr (E + 16) 3 + 2147450880))) tmp gap
    /\ rs_fake m' ff fp hw optc j56 ect_cells j120 0 248
    /\ rw_cells bsegs m' fb (FlatBufCells (mkFB (fb_begin FB) (fb_in FB) (fb_out FB + k) (fb_last FB) (fb_end FB)))
    /\ rw_cells bsegs m' E (ErrCodeCells (rs_ec iseof))
    /\ as_RFS H ((2, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi
    /\ accessible m' E 24 /\ accessible m' fb 48
    /\ AXStatics2 m' /\ AMiscVt48 m'.

Lemma rs_read1 : forall rax sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s5x t3 t4 t5 t6
    (F : bvmap 5 word) fc (m0 m : mem) (LF : list fframe) (lo shi spa ff fp E bs fb P tot k : Z) (FB : fbv) (iseof : bool)
    (hw : word) (tmp gap optc ectc : list cell) (j56 j120 : list byte),
  as_RFS H LF m0 ->
  rs_frame m sp spa ff E bs P fb (C8 (wz (Z.shiftr (E + 16) 3 + 2147450880))) tmp gap ->
  rs_fake m ff fp hw optc j56 ectc j120 0 248 ->
  as_RFS H ((2, ff, fp) :: LF) m -> fresh_frame H LF 2 ff fp ->
  rw_cells bsegs m fb (FlatBufCells FB) -> fb mod 8 = 0 -> aapp fb 48 -> fsobj H LF fb 48 -> accessible m fb 48 ->
  0 < fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_last FB <= fb_end FB -> fb_end FB <= aceil ->
  0 <= k <= fb_last FB - fb_out FB ->
  rw_cells bsegs m E (ErrCodeCells (rs_ec iseof)) -> aapp E 24 -> fsobj H LF E 24 -> accessible m E 24 -> E mod 8 = 0 ->
  (fb + 48 <= E \/ E + 24 <= fb) ->
  AXStatics2 m -> AMiscVt48 m ->
  stk bsegs m lo spa -> lo + AINTRIN_STACK <= spa -> aceil <= lo ->
  0 <= bs < 2^64 -> 0 <= P < 2^64 -> 0 <= tot < 2^64 ->
  mem_inv bsegs m -> ACONST m -> stack0 m lo shi ->
  evt bsegs (rs_read1_post sp spa gp tp F fc LF lo shi E bs fb P tot k ff fp FB iseof hw tmp gap optc j56 j120 m)
    (rs_ms RS_RSRET rax sp spa gp tp t0 t1 t2 E (wz k) a1 a2 a3 a4 a5 a6 a7 tot fb ff s5x (wz (E + 16)) t3 t4 t5 t6 F fc m).
